const ev = $('On Stripe Subscription Event').first().json;
const cfg = $('Community Configuration').first().json;
const customer = $input.first().json || {};
const sub = ev.data?.object || {};
const prevStatus = String(ev.data?.previous_attributes?.status || '');
const subStatus = String(sub.status || '');
const eventType = String(ev.type || '');

const rawPhone = String(
  customer.phone || customer.metadata?.whatsapp_phone || sub.metadata?.whatsapp_phone || ''
).trim();
const cleanPhone = rawPhone.replace(/\D/g, '');
if (cleanPhone.length < 8) return [];

let lifecycleAction = 'ignore';
if (eventType === 'customer.subscription.deleted' || ['canceled', 'unpaid', 'incomplete_expired'].includes(subStatus)) {
  lifecycleAction = 'revoke_access';
} else if (subStatus === 'past_due') {
  lifecycleAction = 'grace_warning';
} else if (['active', 'trialing'].includes(subStatus)) {
  if (eventType === 'customer.subscription.created' || (prevStatus && !['active', 'trialing'].includes(prevStatus))) {
    lifecycleAction = 'grant_access';
  }
}
if (lifecycleAction === 'ignore') return [];

const planName = String(
  sub.items?.data?.[0]?.price?.nickname || sub.items?.data?.[0]?.plan?.nickname || 'VIP Membership'
).trim();
const graceHours = Number(cfg.graceHours || 48);
const graceExpiresAt = new Date(Date.now() + graceHours * 3600 * 1000).toISOString();

return [{
  json: {
    eventType,
    lifecycleAction,
    subStatus,
    subscriptionId: String(sub.id || ''),
    customerId: String(sub.customer || customer.id || ''),
    cleanPhone,
    memberName: String(customer.name || 'Member').trim(),
    email: String(customer.email || '').trim(),
    planName,
    graceHours,
    graceExpiresAt,
    communityName: cfg.communityName,
    vipGroupId: cfg.vipGroupId,
    spreadsheetId: cfg.spreadsheetId,
    slackOpsChannelId: cfg.slackOpsChannelId,
    checkoutUrl: cfg.checkoutUrl,
    portalReturnUrl: cfg.portalReturnUrl,
  },
}];

const ev = $('When Someone Joins VIP Group').first().json;
const cfg = $('Guard Configuration').first().json;
const chatId = String(ev.chat?.id || ev.groupId || '').trim();
if (!chatId || chatId !== String(cfg.vipGroupId || '').trim()) return [];

const adminSet = new Set(
  String(cfg.adminPhonesCsv || '')
    .split(',')
    .map((p) => p.replace(/\D/g, ''))
    .filter((p) => p.length >= 8)
);

const rawParticipants = Array.isArray(ev.participants)
  ? ev.participants
  : ev.from?.id ? [ev.from.id] : [];

const results = [];
for (const entry of rawParticipants) {
  const digits = String(entry || '').split('@')[0].replace(/\D/g, '');
  if (digits.length < 8 || adminSet.has(digits)) continue;
  results.push({
    json: {
      joinerPhone: digits,
      vipGroupId: cfg.vipGroupId,
      communityName: cfg.communityName,
      spreadsheetId: cfg.spreadsheetId,
      slackOpsChannelId: cfg.slackOpsChannelId,
      checkoutUrl: cfg.checkoutUrl,
    },
  });
}
return results;

const joiners = $('Filter Target VIP Group Join').all().map((i) => i.json);
const rows = $input.all().map((i) => i.json).filter((r) => r && r.phone);
const byPhone = new Map();
for (const r of rows) {
  const phone = String(r.phone || '').replace(/\D/g, '');
  if (phone) byPhone.set(phone, r);
}
return joiners.map((joiner) => {
  const row = byPhone.get(joiner.joinerPhone);
  const isAuthorized = Boolean(row && (row.status === 'Active' || row.status === 'Past Due'));
  return {
    json: {
      ...joiner,
      isAuthorized,
      customerId: row ? String(row.customerId || '') : '',
      memberName: row ? String(row.memberName || 'New Member') : 'Unknown',
      planName: row ? String(row.planName || 'VIP') : '',
    },
  };
});

const cfg = $('Audit Configuration').first().json;
const rawItems = $input.all().map((i) => i.json);
const members = [];
for (const item of rawItems) {
  if (Array.isArray(item.members)) members.push(...item.members);
  else if (Array.isArray(item.value?.members)) members.push(...item.value.members);
  else if (item.id) members.push(item);
}
const adminSet = new Set(
  String(cfg.adminPhonesCsv || '')
    .split(',')
    .map((p) => p.replace(/\D/g, ''))
    .filter((p) => p.length >= 8)
);
const livePhones = [];
for (const m of members) {
  if (m.isAdmin || m.isSuperAdmin) continue;
  const idStr = String(m.id || '');
  if (idStr.endsWith('@lid')) continue;
  const phone = idStr.split('@')[0].replace(/\D/g, '');
  if (phone.length < 8 || adminSet.has(phone)) continue;
  livePhones.push(phone);
}
return [{ json: { ...cfg, livePhones: [...new Set(livePhones)], totalLiveCount: members.length } }];

const live = $('Extract Live Non-Admin Phones').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.phone);
const now = Date.now();

const byPhone = new Map();
for (const row of rows) {
  const p = String(row.phone || '').replace(/\D/g, '');
  if (p) byPhone.set(p, row);
}

const evictions = [];
for (const phone of live.livePhones || []) {
  const row = byPhone.get(phone);
  if (!row) {
    evictions.push({
      json: {
        action: 'evict',
        phone,
        customerId: '',
        memberName: 'Unlisted Member',
        reason: 'Not found in paid Stripe ledger',
        vipGroupId: live.vipGroupId,
        communityName: live.communityName,
        spreadsheetId: live.spreadsheetId,
        slackOpsChannelId: live.slackOpsChannelId,
        checkoutUrl: live.checkoutUrl,
      },
    });
    continue;
  }
  const graceExpired = row.status === 'Past Due' && row.graceExpiresAt && Date.parse(row.graceExpiresAt) <= now;
  const revoked = row.status !== 'Active' && row.status !== 'Past Due';
  if (graceExpired || revoked) {
    evictions.push({
      json: {
        action: 'evict',
        phone,
        customerId: String(row.customerId || ''),
        memberName: String(row.memberName || 'Member'),
        reason: graceExpired ? '48h Past-Due grace period expired' : `Ledger status is ${row.status}`,
        vipGroupId: live.vipGroupId,
        communityName: live.communityName,
        spreadsheetId: live.spreadsheetId,
        slackOpsChannelId: live.slackOpsChannelId,
        checkoutUrl: live.checkoutUrl,
      },
    });
  }
}

if (evictions.length > 0) return evictions;
return [{
  json: {
    action: 'clean_summary',
    totalLiveCount: live.totalLiveCount,
    checkedMembers: (live.livePhones || []).length,
    communityName: live.communityName,
    slackOpsChannelId: live.slackOpsChannelId,
  },
}];
